// Materialize a new v2 envelope after topology/path/settings changes. The old
// preservation writer remains available for byte-preserving compatibility.
// No bytes are published on failure; offsets/counts are regenerated by parsing.
bool RebuildPmmV2(const PmmSceneDocument&, PmmSceneDocument&, std::string& reason);
PmmSceneDocument NewPmmScene();
bool RebuildPmmBoneInterpolation(PmmKeyTrack<PmmBoneKey>&, std::size_t channel,
                                 std::uint32_t frame);

template <class T>
bool PmmTrackChains(const PmmKeyTrack<T>& track, std::vector<std::vector<T>>& chains) {
    if (track.dense.size() > 100000 || track.sparse.size() > 100000)
        return false;
    std::map<std::uint32_t, const T*> sparse;
    for (const auto& entry : track.sparse)
        if (entry.index < 0 || std::size_t(entry.index) < track.dense.size() ||
            std::size_t(entry.index) >= track.dense.size() + 100000 ||
            !sparse.emplace(std::uint32_t(entry.index), &entry.value).second)
            return false;
    std::set<std::uint32_t> visited;
    std::vector<std::vector<T>> result(track.dense.size());
    for (std::size_t root = 0; root < track.dense.size(); ++root) {
        const T* key = &track.dense[root];
        // Native unlinking writes table[next].previous even when next is the
        // zero sentinel. Root 0 can therefore retain a predecessor (including
        // a subsequently freed slot); it is never followed as a chain edge.
        if (key->frame || (root && key->previous) || key->previous >= track.dense.size() + 100000)
            return false;
        auto index = std::uint32_t(root);
        result[root].push_back(*key);
        while (key->next) {
            const auto next = sparse.find(key->next);
            if (next == sparse.end() || !visited.insert(next->first).second ||
                next->second->previous != index || next->second->frame <= key->frame ||
                next->second->frame > 0x7fffffffU)
                return false;
            index = next->first;
            key = next->second;
            result[root].push_back(*key);
        }
    }
    if (visited.size() != sparse.size())
        return false;
    chains = std::move(result);
    return true;
}
template <class T>
bool BuildPmmTrack(const std::vector<std::vector<T>>& chains, PmmKeyTrack<T>& output) {
    if (chains.size() > 100000)
        return false;
    PmmKeyTrack<T> next;
    next.dense.resize(chains.size());
    next.denseRecordOffsets.resize(chains.size());
    for (std::size_t root = 0; root < chains.size(); ++root) {
        const auto& keys = chains[root];
        if (keys.empty() || keys.front().frame)
            return false;
        auto index = std::uint32_t(root);
        for (std::size_t k = 0; k < keys.size(); ++k) {
            auto value = keys[k];
            if (value.frame > 0x7fffffffU || (k && keys[k - 1].frame >= value.frame))
                return false;
            value.previous = k ? index : 0;
            const auto current = k ? std::uint32_t(next.dense.size() + next.sparse.size()) : index;
            value.next = k + 1 == keys.size()
                             ? 0
                             : std::uint32_t(next.dense.size() + next.sparse.size() + (k ? 1 : 0));
            if (!k)
                next.dense[root] = value;
            else {
                if (next.sparse.size() >= 100000)
                    return false;
                next.sparse.push_back({std::int32_t(current), 0, value});
            }
            index = current;
        }
    }
    output = std::move(next);
    return true;
}

// Insert one frame before all non-root keys at/after the cursor. Stable record
// indices, links, selection bytes and payloads are retained. Validate the whole
// operation first so an overflow never leaves a partially shifted track.
template <class T>
bool InsertPmmFrameLine(PmmKeyTrack<T>& track, std::uint32_t frame, unsigned& affected) {
    std::vector<std::vector<T>> chains;
    if (frame > 0x7fffffffU || !PmmTrackChains(track, chains))
        return false;
    unsigned count = 0;
    for (const auto& record : track.sparse)
        if (record.value.frame >= frame) {
            if (record.value.frame == 0x7fffffffU)
                return false;
            ++count;
        }
    for (auto& record : track.sparse)
        if (record.value.frame >= frame)
            ++record.value.frame;
    affected = count;
    return true;
}
template <class T> bool RegisterPmmKey(PmmKeyTrack<T>& track, std::size_t channel, T key) {
    std::vector<std::vector<T>> chains;
    if (key.frame > 0x7fffffffU || !PmmTrackChains(track, chains) || channel >= chains.size())
        return false;
    std::map<std::uint32_t, T*> records;
    for (std::size_t i = 0; i < track.dense.size(); ++i)
        records.emplace(std::uint32_t(i), &track.dense[i]);
    for (auto& record : track.sparse)
        records.emplace(std::uint32_t(record.index), &record.value);
    auto index = std::uint32_t(channel);
    while (records.at(index)->frame < key.frame && records.at(index)->next)
        index = records.at(index)->next;
    auto& current = *records.at(index);
    if (current.frame == key.frame) {
        // A payload overwrite must not relocate any key, including this one.
        key.previous = current.previous;
        key.next = current.next;
        current = std::move(key);
        return true;
    }
    if (track.sparse.size() >= 100000)
        return false;
    // Button registration reuses the first free record after the roots.
    auto free = std::uint32_t(track.dense.size());
    while (records.count(free))
        ++free;
    if (current.frame < key.frame) {
        key.previous = index;
        key.next = 0;
        current.next = free;
    } else {
        key.previous = current.previous;
        key.next = index;
        records.at(current.previous)->next = free;
        current.previous = free;
    }
    track.sparse.push_back({std::int32_t(free), 0, std::move(key)});
    std::sort(track.sparse.begin(), track.sparse.end(),
              [](const auto& a, const auto& b) { return a.index < b.index; });
    return true;
}
template <class T>
bool DeletePmmKey(PmmKeyTrack<T>& track, std::size_t channel, std::uint32_t frame) {
    // MMD retains the frame-zero root; deleting it cannot destroy the channel.
    if (!frame)
        return false;
    std::vector<std::vector<T>> chains;
    if (!PmmTrackChains(track, chains) || channel >= chains.size())
        return false;
    const auto& keys = chains[channel];
    const auto found =
        std::find_if(keys.begin(), keys.end(), [frame](const T& k) { return k.frame == frame; });
    if (found == keys.end())
        return false;
    std::map<std::uint32_t, T*> records;
    for (std::size_t i = 0; i < track.dense.size(); ++i)
        records.emplace(std::uint32_t(i), &track.dense[i]);
    for (auto& record : track.sparse)
        records.emplace(std::uint32_t(record.index), &record.value);
    auto& previous = *records.at(found->previous);
    const auto removed = previous.next;
    previous.next = found->next;
    records.at(found->next)->previous = found->previous;
    track.sparse.erase(std::find_if(track.sparse.begin(), track.sparse.end(),
                                    [&](const auto& record) { return record.index == removed; }));
    return true;
}
